codon={}; i=0
for a in bases:
    for b in bases:
        for c in bases:
            codon[a+b+c]=aas[i]; i+=1
def tr(s): return "".join(codon.get(s[i:i+3],"X") for i in range(0,len(s)-2,3))

def orfs(s, strand):
    out=[]
    for f in range(3):
        p = tr(s[f:])
        pos = f
        for part in p.split("*"):
            L=len(part)*3+3
            if len(part)>=60:
                # coords on the strand used
                out.append((strand, f, pos, pos+L, len(part), part))
            pos += L
    return out

